  return Array.from({length: 1000}, (_, i) => ({
    id: `trade-${i}`,
    timestamp: Date.now() - (i * 60),
    symbol: 'AAPL',
    price: 150 + (i % 10),
    quantity: 100
  }));
};

// Event replay simulation
const replayEvents = (events, delay) => {
  events.forEach(event => {
    setTimeout(() => producer.send(event), delay);
  });
};

// UI verification with Playwright
const verifyDashboard = async (page, expectedAggregates) => {
